"""Read-only lineage audit and EDA; writes only this isolated audit package."""
from pathlib import Path
import hashlib, json, math
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score

R=Path(__file__).resolve().parent; STAGE=R.parent; PLOTS=R/'eda_plots'
HIST_DATA=STAGE/'input'/'cookchem_molecular_retention_preprocessed.csv'; HIST_OUT=STAGE/'outputs'
FINAL=STAGE/'dataset_expansion_1000'/'batch_021'/'updated_master_dataset.csv'; COMP=STAGE/'molecular_vs_source_validation_audit'/'validation_summary.json'
TARGET='target_value_percent'
def m(a,p): return {'r2':float(r2_score(a,p)),'mae':float(mean_absolute_error(a,p)),'rmse':float(math.sqrt(mean_squared_error(a,p)))}
def savefig(name): plt.tight_layout();plt.savefig(PLOTS/name,dpi=170);plt.close()
def desc(s,name,unit=''):
 q=s.dropna(); return {'section':'target_or_numeric','metric':name,'unit':unit,'n':len(q),'missing':int(s.isna().sum()),'mean':float(q.mean()) if len(q) else np.nan,'median':float(q.median()) if len(q) else np.nan,'std':float(q.std(ddof=1)) if len(q)>1 else np.nan,'min':float(q.min()) if len(q) else np.nan,'q1':float(q.quantile(.25)) if len(q) else np.nan,'q3':float(q.quantile(.75)) if len(q) else np.nan,'max':float(q.max()) if len(q) else np.nan}
def stats_by(d,by):
 return d.groupby(by)[TARGET].agg(observations='size',mean='mean',median='median',std='std',min='min',max='max').reset_index().sort_values('observations',ascending=False)
def main():
 PLOTS.mkdir(exist_ok=True); h=pd.read_csv(HIST_DATA); b=pd.read_csv(HIST_OUT/'stageA_benchmark_results.csv'); hf=pd.read_csv(HIST_OUT/'stageA_fold_results.csv'); ho=pd.read_csv(HIST_OUT/'stageA_oof_predictions.csv'); d=pd.read_csv(FINAL)
 # Historical verification against persisted OOF data and source input.
 x=ho[ho.Model.eq('XGBoost_tuned')].copy(); stored=b[b.Model.eq('XGBoost_tuned')].iloc[0]; input_target=h.set_index('Record_ID').loc[x.Record_ID.astype(str),'Retention_Final'].to_numpy(float)
 assert len(x)==len(h)==1124 and not x.Record_ID.duplicated().any() and np.allclose(x.actual.to_numpy(float),input_target)
 rec=m(x.actual,x.predicted); fold_recalc=x.groupby('fold').apply(lambda q:pd.Series(m(q.actual,q.predicted))).reset_index(); expected=hf[hf.Model.eq('XGBoost_tuned')][['Fold','MAE','RMSE','R2','sample_count']].sort_values('Fold').reset_index(drop=True)
 actual=fold_recalc.sort_values('fold').reset_index(drop=True); assert np.allclose([rec['r2'],rec['mae'],rec['rmse']],[stored.R2,stored.MAE,stored.RMSE]) and np.allclose(actual.r2,expected.R2)
 assert x.groupby('Canonical_Molecular_ID').fold.nunique().max()==1
 pd.DataFrame([desc(h.Retention_Final,'Retention_Final','historical stored target')]).to_csv(R/'historical_retention_final_distribution.csv',index=False)
 plt.figure(figsize=(7,4));plt.hist(h.Retention_Final,bins=45,color='#8064a2');plt.xlabel('Historical Retention_Final (stored scale)');plt.ylabel('Observations');plt.title('Historical target distribution only');savefig('historical_retention_final_histogram.png')
 # Final data contract and EDA inputs.
 assert 'Retention_Final' not in d.columns and d.target_name.eq('apparent_concentration_ratio_percent').all()
 assert np.allclose(d[TARGET],100*d.cooked_concentration/d.raw_concentration,atol=.01,rtol=0)
 key=['doi','compound','food_matrix','cooking_method_normalized','Cooking_Time_min','raw_concentration','cooked_concentration']; dup=int(d.duplicated(key).sum())
 missing=d.isna().sum().sort_values(ascending=False).rename_axis('column').reset_index(name='missing_count');missing['missing_percent']=100*missing.missing_count/len(d);missing.to_csv(R/'missingness_summary.csv',index=False)
 compound=d.groupby('compound').size().reset_index(name='observations').sort_values('observations',ascending=False);compound.to_csv(R/'compound_observation_counts.csv',index=False)
 source=d.groupby('doi').agg(observations=('observation_id','size'),compounds=('compound','nunique'),matrices=('food_matrix','nunique'),methods=('cooking_method_normalized','nunique'),target_mean=(TARGET,'mean'),target_median=(TARGET,'median'),target_std=(TARGET,'std')).reset_index().sort_values('observations',ascending=False);source.to_csv(R/'source_observation_counts.csv',index=False)
 stats=pd.DataFrame([desc(d[TARGET],TARGET,'percent'),desc(d.raw_concentration,'raw_concentration','reported concentration unit'),desc(d.cooked_concentration,'cooked_concentration','reported concentration unit')]); stats.to_csv(R/'eda_summary_statistics.csv',index=False)
 by_comp=stats_by(d,'compound');by_comp.to_csv(R/'target_by_compound.csv',index=False);by_src=stats_by(d,'doi');by_src.to_csv(R/'target_by_source.csv',index=False);d.groupby('food_matrix').size().reset_index(name='observations').sort_values('observations',ascending=False).to_csv(R/'food_matrix_observation_counts.csv',index=False);d.groupby('cooking_method_normalized').size().reset_index(name='observations').sort_values('observations',ascending=False).to_csv(R/'cooking_method_observation_counts.csv',index=False);pd.crosstab(d.compound_class,d.cooking_method_normalized).to_csv(R/'compound_class_by_method.csv')
 numeric=['raw_concentration','cooked_concentration',TARGET,'Temperature_C','Cooking_Time_min','RDKit_Molecular_Weight','RDKit_LogP','RDKit_TPSA','RDKit_HBond_Donors','RDKit_HBond_Acceptors','RDKit_Rotatable_Bonds','RDKit_Aromatic_Rings','RDKit_Hydroxyl_Groups']; desc_cov=pd.DataFrame({'column':numeric,'finite_count':[int(np.isfinite(pd.to_numeric(d[c],errors='coerce')).sum()) for c in numeric],'missing_count':[int(pd.to_numeric(d[c],errors='coerce').isna().sum()) for c in numeric]});desc_cov.to_csv(R/'molecular_descriptor_and_numeric_coverage.csv',index=False)
 q1,q3=d[TARGET].quantile([.25,.75]);iqr=q3-q1;out=((d[TARGET]<q1-1.5*iqr)|(d[TARGET]>q3+1.5*iqr));outliers=d.loc[out,['observation_id','doi','compound','food_matrix','cooking_method_normalized',TARGET]].sort_values(TARGET);outliers.to_csv(R/'target_iqr_outliers.csv',index=False)
 # EDA plots.
 plt.figure(figsize=(7,4));plt.hist(d[TARGET],bins=45,color='#31708f');plt.xlabel('Apparent concentration ratio (%)');plt.ylabel('Observations');plt.title('Target distribution');savefig('target_histogram.png')
 plt.figure(figsize=(7,4));plt.boxplot(d[TARGET],vert=False);plt.xlabel('Apparent concentration ratio (%)');plt.title('Target boxplot');savefig('target_boxplot.png')
 topc=compound.head(20).sort_values('observations');plt.figure(figsize=(8,6));plt.barh(topc.compound,topc.observations,color='#4f81bd');plt.xlabel('Observations');plt.title('Top compounds by observation count');savefig('compound_observation_counts.png')
 tops=source.head(20).sort_values('observations');plt.figure(figsize=(8,6));plt.barh(tops.doi,tops.observations,color='#8064a2');plt.xlabel('Observations');plt.title('Top DOI families by observation count');savefig('source_observation_counts.png')
 methods=sorted(d.cooking_method_normalized.unique());plt.figure(figsize=(max(8,len(methods)*.65),5));plt.boxplot([d.loc[d.cooking_method_normalized.eq(x),TARGET] for x in methods],labels=methods,showfliers=False);plt.xticks(rotation=45,ha='right');plt.ylabel('Apparent concentration ratio (%)');plt.title('Target by cooking method');savefig('target_by_cooking_method.png')
 foods=d.food_matrix.value_counts().head(15).index.tolist();plt.figure(figsize=(10,5));plt.boxplot([d.loc[d.food_matrix.eq(x),TARGET] for x in foods],labels=foods,showfliers=False);plt.xticks(rotation=55,ha='right');plt.ylabel('Apparent concentration ratio (%)');plt.title('Target by common food matrices');savefig('target_by_food_matrix.png')
 descs=['RDKit_Molecular_Weight','RDKit_LogP','RDKit_TPSA','RDKit_HBond_Donors','RDKit_HBond_Acceptors','RDKit_Rotatable_Bonds','RDKit_Aromatic_Rings','RDKit_Hydroxyl_Groups'];fig,axs=plt.subplots(2,4,figsize=(12,6));
 for ax,c in zip(axs.ravel(),descs):ax.hist(d[c],bins=20,color='#6aa84f');ax.set_title(c.replace('RDKit_',''));ax.set_ylabel('Count')
 fig.suptitle('Molecular descriptor distributions');fig.tight_layout();fig.savefig(PLOTS/'descriptor_distributions.png',dpi=170);plt.close(fig)
 corr=d[numeric].apply(pd.to_numeric,errors='coerce').corr();fig,ax=plt.subplots(figsize=(9,8));im=ax.imshow(corr,cmap='coolwarm',vmin=-1,vmax=1);ax.set_xticks(range(len(numeric)),[x.replace('RDKit_','') for x in numeric],rotation=75,ha='right',fontsize=7);ax.set_yticks(range(len(numeric)),[x.replace('RDKit_','') for x in numeric],fontsize=7);fig.colorbar(im,ax=ax,label='Pearson correlation');ax.set_title('Numerical-variable correlation heatmap');fig.tight_layout();fig.savefig(PLOTS/'numeric_correlation_heatmap.png',dpi=170);plt.close(fig)
 miss=missing[missing.missing_count.gt(0)].sort_values('missing_count');plt.figure(figsize=(8,6));plt.barh(miss.column,miss.missing_percent,color='#cc4125');plt.xlabel('Missing values (%)');plt.title('Missingness overview');savefig('missingness_overview.png')
 ts=by_src.head(20).sort_values('observations');plt.figure(figsize=(9,6));plt.errorbar(ts['mean'],range(len(ts)),xerr=ts['std'].fillna(0),fmt='o',color='#674ea7');plt.yticks(range(len(ts)),ts.doi,fontsize=7);plt.xlabel('Mean target ± source SD (%)');plt.title('Source-wise target variation');savefig('source_target_variation.png')
 # EDA report values.
 coverage={'one':int((compound.observations==1).sum()),'two_or_more':int((compound.observations>=2).sum()),'five_or_more':int((compound.observations>=5).sum()),'ten_or_more':int((compound.observations>=10).sum()),'twenty_or_more':int((compound.observations>=20).sum())}; positive=(d[TARGET]>100).sum();zero=(d[TARGET]==0).sum();negative=(d[TARGET]<0).sum(); top3=int(source.head(3).observations.sum());
 report=['# Final dataset EDA audit','','## Audit finding','- Earlier EDA/diagnostic artifacts exist for historical and 439-row recovery datasets (`diagnostics_v0_1`, `recovery_v0_9`, and `final_prototype`). Batch 021 contains coverage and post-1,000 model-evaluation outputs, but no comprehensive final-1,016 EDA script/report with the requested distribution, missingness, source, food, descriptor and visual analyses was found. This package supplies that missing final-dataset EDA.','','## Dataset structure',f'- Rows: {len(d)}. Compound labels: {d.compound.nunique()}. Canonical molecular IDs: {d.canonical_molecular_id.nunique()}. DOI families: {d.doi.nunique()}. Food matrices: {d.food_matrix.nunique()}. Normalized cooking methods: {d.cooking_method_normalized.nunique()}.',f'- Exact duplicate experiment keys: {dup}.',f'- Largest DOI family contributes {int(source.iloc[0].observations)} rows ({source.iloc[0].observations/len(d)*100:.2f}%); top three contribute {top3} ({top3/len(d)*100:.2f}%).','','## Target',f'- `Retention_Final` is absent from this final dataset. It is therefore not silently recreated or analysed as a final target. The separate `historical_retention_final_distribution.csv` and plot are historical-only context.',f'- `target_value_percent` is the retained apparent concentration-ratio target. Mean {d[TARGET].mean():.2f}, median {d[TARGET].median():.2f}, SD {d[TARGET].std():.2f}, range {d[TARGET].min():.2f}–{d[TARGET].max():.2f}.',f'- Values above 100: {int(positive)}; zero: {int(zero)}; negative: {int(negative)}; IQR outliers: {int(out.sum())}. Values above 100 represent a reported concentration increase, not automatically a total-mass-retention increase.','','## Coverage and missingness',f'- Compounds with exactly one observation: {coverage["one"]}; at least 2: {coverage["two_or_more"]}; at least 5: {coverage["five_or_more"]}; at least 10: {coverage["ten_or_more"]}; at least 20: {coverage["twenty_or_more"]}.',f'- All eight molecular descriptor columns are finite for {int(desc_cov[desc_cov.column.str.startswith("RDKit_")].finite_count.min())}/{len(d)} rows. The master does not carry canonical SMILES, so this audit confirms descriptor completeness rather than independently revalidating chemical structures.',f'- The principal experimental-field gaps are temperature ({int(d.Temperature_C.isna().sum())}) and cooking time ({int(d.Cooking_Time_min.isna().sum())}).','','## Interpretation limits','- Plots and correlations are descriptive. They do not establish causal effects of cooking method, food, source, or molecular properties.','- The dataset retains source and measurement-basis heterogeneity. EDA demonstrates composition and imbalance, not that any one factor explains held-out performance.']
 (R/'final_dataset_eda_report.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
 hist_report=['# Historical `Retention_Final` molecular-grouped verification','','## Verified historical result',f'- Dataset: `stageA/input/cookchem_molecular_retention_preprocessed.csv`, {len(h)} observations and {h.Canonical_Molecular_ID.nunique()} molecular groups.','- Target: `Retention_Final`.','- Model: `XGBoost_tuned`; 450 estimators, depth 3, learning rate 0.03, min child weight 3, subsample 0.8, column subsample 0.8, L2 lambda 5, seed 42.','- Split: five-fold `GroupKFold` on `Canonical_Molecular_ID`; saved OOF predictions establish each molecular group appears in one fold.','- Saved OOF recomputation: pooled R² '+f'{rec["r2"]:.4f}'+', MAE '+f'{rec["mae"]:.4f}'+', RMSE '+f'{rec["rmse"]:.4f}'+'.','- Mean fold R² '+f'{fold_recalc.r2.mean():.4f}'+', SD '+f'{fold_recalc.r2.std(ddof=1):.4f}'+'. The fold metrics are stored in `original_target_molecular_cv_metrics.csv`.','- The historical script builds preprocessing pipelines inside each outer training fold and applies log1p/expm1 to the target. Saved OOF predictions are complete and correspond exactly to input `Retention_Final` values.','', '## Scientific status','- This is a genuine historical result within its molecular-grouped design, not a result on the final 1,016-row dataset. The historical script and manifest state that `Retention_Final` construction is unresolved, so it is not a verified scientific retention target.','- It predates the later recovery packages and their explicit apparent-concentration-ratio target contract. It cannot be treated as a validated final-target result or as unseen-source generalisation.','- Batch 021 does not contain a `Retention_Final` column. A final-dataset original-target rerun is therefore not admissible and was not fabricated.']
 (R/'historical_model_verification.md').write_text('\n'.join(hist_report)+'\n',encoding='utf-8')
 metrics=fold_recalc.rename(columns={'fold':'fold','r2':'r2','mae':'mae','rmse':'rmse'});metrics.insert(0,'experiment','historical_retention_final_molecular_grouped_xgboost_tuned');metrics['n_test']=expected.sample_count.to_numpy();metrics['mean_fold_r2']=fold_recalc.r2.mean();metrics['std_fold_r2']=fold_recalc.r2.std(ddof=1);metrics.to_csv(R/'original_target_molecular_cv_metrics.csv',index=False)
 recent=json.loads(COMP.read_text())['results']; recent_map={x['validation_strategy']:x for x in recent}; comparison=pd.DataFrame([{'Experiment':'Historical original-target molecular-grouped','Dataset version':'historical input / 1,124 rows','Target':'Retention_Final (unresolved construction)','Model':'XGBoost_tuned (450 trees)','Validation':'GroupKFold(5), Canonical_Molecular_ID','Mean fold R2':float(fold_recalc.r2.mean()),'Pooled OOF R2':rec['r2'],'Status':'historical, verified from saved OOF'}, {'Experiment':'Final dataset original-target molecular-grouped','Dataset version':'Batch 021 / 1,016 rows','Target':'Retention_Final','Model':'not run','Validation':'not applicable','Mean fold R2':np.nan,'Pooled OOF R2':np.nan,'Status':'not admissible: target column absent'}, {'Experiment':'Final apparent-ratio molecular-grouped','Dataset version':'Batch 021 / 1,016 rows','Target':'target_value_percent','Model':'ExtraTrees (25 trees)','Validation':'GroupKFold(5), canonical_molecular_id','Mean fold R2':recent_map['molecular_grouped']['mean_fold_r2'],'Pooled OOF R2':recent_map['molecular_grouped']['r2'],'Status':'current fixed audit'}, {'Experiment':'Final apparent-ratio source-held-out','Dataset version':'Batch 021 / 1,016 rows','Target':'target_value_percent','Model':'ExtraTrees (25 trees)','Validation':'GroupKFold(5), DOI','Mean fold R2':recent_map['source_held_out']['mean_fold_r2'],'Pooled OOF R2':recent_map['source_held_out']['r2'],'Status':'current fixed audit'}]);comparison.to_csv(R/'historical_experiment_comparison.csv',index=False)
 (R/'README.md').write_text('# Reproduction\n\nRun `python run_historical_model_and_eda_audit.py` in this directory. It reads immutable historical/final Stage A artifacts and writes only this audit package.\n',encoding='utf-8')
 (R/'SHA256SUMS.txt').write_text('\n'.join(f'{hashlib.sha256(p.read_bytes()).hexdigest()}  {p.name}' for p in sorted(R.rglob('*')) if p.is_file() and p.name!='SHA256SUMS.txt')+'\n',encoding='utf-8')
 print(json.dumps({'historical_verified':rec,'historical_mean_fold_r2':float(fold_recalc.r2.mean()),'final_has_retention_final':False,'final_rows':len(d),'final_eda_created':True},indent=2))
if __name__=='__main__': main()
